<script>
const gstToggle=document.getElementById('gstEnabledToggle');
const gstHidden=document.getElementById('gstEnabledValue');
const gstEnabled=()=>gstToggle.checked;
const round = x => Math.round((x+Number.EPSILON)*100)/100;
const n = el => Math.max(0,Number(el?.value||0)||0);
const display = x => new Intl.NumberFormat('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}).format(round(x));
const clean = x => String(Number(round(x).toFixed(2)));
document.querySelectorAll('input.num').forEach(el=>{if(el.value.trim()&&Number.isFinite(Number(el.value)))el.value=String(Number(el.value));el.addEventListener('focus',()=>el.select())});
function update(){let gross=0,discount=0,taxable=0,tax=0;
document.querySelectorAll('.quote-row').forEach(row=>{
 const qty=Number(row.querySelector('[data-label="Requested Quantity"]').textContent.trim().split(' ')[0].replace(/,/g,''))||0;
 const rate=round(n(row.querySelector('.rate'))),p=row.querySelector('.discount-percent'),a=row.querySelector('.discount-amount'),mode=row.querySelector('.discount-mode');
 let unitDiscount=0;
 if(mode.value==='percent'){unitDiscount=round(rate*Math.min(100,n(p))/100);if(document.activeElement!==a)a.value=unitDiscount?clean(unitDiscount):'';}
 else {unitDiscount=round(n(a));if(rate>0&&document.activeElement!==p)p.value=unitDiscount?clean(unitDiscount/rate*100):'';}
 const base=round(Math.max(0,rate-unitDiscount)*qty),g=round(qty*rate),d=round(qty*unitDiscount),gst=gstEnabled()?round(base*Math.min(100,n(row.querySelector('.gst')))/100):0;
 row.querySelector('.net-unit').textContent=display(Math.max(0,rate-unitDiscount));row.querySelector('.taxable').textContent=display(base);
 row.querySelector('.unit-gst').textContent=gstEnabled()?display(Math.max(0,rate-unitDiscount)+ (qty?gst/qty:0)):'N/A';row.querySelector('.line-total').textContent=gstEnabled()?display(base+gst):'N/A';
 gross+=g;discount+=d;taxable+=base;tax+=gst;
});const other=round([...document.querySelectorAll('.extra-charge')].reduce((sum,el)=>sum+n(el),0));
for(const [id,val] of Object.entries({grossTotal:gross,discountTotal:discount,productTotal:taxable,taxTotal:tax,withGstTotal:taxable+tax,otherTotal:other,netTotal:taxable+tax+other}))document.getElementById(id).textContent=display(val);
}
gstToggle.addEventListener('change',()=>{gstHidden.value=gstEnabled()?'1':'0';document.querySelectorAll('.gst').forEach(el=>{el.disabled=!gstEnabled() || {{ $locked ? 'true' : 'false' }};});document.body.classList.toggle('gst-off',!gstEnabled());update();});
document.querySelectorAll('.gst').forEach(el=>{el.disabled=!gstEnabled() || {{ $locked ? 'true' : 'false' }};});document.body.classList.toggle('gst-off',!gstEnabled());
document.querySelectorAll('.quote-row').forEach(row=>{row.querySelector('.discount-percent').addEventListener('input',()=>{row.querySelector('.discount-mode').value='percent';update()});row.querySelector('.discount-amount').addEventListener('input',()=>{row.querySelector('.discount-mode').value='amount';update()})});
document.getElementById('quoteForm').addEventListener('submit',()=>{if(!gstEnabled())document.querySelectorAll('.gst').forEach(el=>{el.disabled=false;el.value='0';});});
document.querySelectorAll('#quoteForm input').forEach(el=>el.addEventListener('input',update));update();
</script></body></html>